files.terraform/main.tf:
# Terraform main configuration
terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.68"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.9"
    }
  }
}

provider "aws" {
  region = var.region
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = { Name = "app-vpc" }
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id
  # No ingress or egress rules – defaults are revoked
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "app-igw" }
}

resource "aws_subnet" "public" {
  count                   = length(var.azs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = var.azs[count.index]
  map_public_ip_on_launch = false
  tags                    = { Name = "public-${count.index}" }
}

resource "aws_subnet" "private" {
  count                   = length(var.azs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index + 10)
  availability_zone       = var.azs[count.index]
  map_public_ip_on_launch = false
  tags                    = { Name = "private-${count.index}" }
}

resource "aws_eip" "nat" {
  domain = "vpc"
  tags   = { Name = "nat-eip" }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id
  tags          = { Name = "nat-gw" }
}

resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "public-rt" }
}

resource "aws_route" "public_default" {
  route_table_id         = aws_route_table.public_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public_assoc" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public_rt.id
}

resource "aws_route_table" "private_rt" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "private-rt" }
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private_rt.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat.id
}

resource "aws_route_table_association" "private_assoc" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_rt.id
}

resource "aws_security_group" "alb_sg" {
  name        = "alb-sg"
  description = "Allow inbound HTTPS"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "ecs_sg" {
  name        = "ecs-sg"
  description = "ECS tasks SG"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.alb_sg.id]
  }
}

resource "aws_lb" "app_alb" {
  name                       = "app-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb_sg.id]
  subnets                    = aws_subnet.public[*].id
  enable_deletion_protection = false
  drop_invalid_header_fields = true
  tags                       = { Name = "app-alb" }

  access_logs {
    bucket  = aws_s3_bucket.alb_logs.bucket
    enabled = true
    prefix  = "alb"
  }
}

resource "aws_lb_target_group" "app_tg" {
  name        = "app-tg"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"
  health_check {
    path                = "/health"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
    matcher             = "200-299"
  }
}

resource "aws_lb_listener" "https_listener" {
  load_balancer_arn = aws_lb.app_alb.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = var.acm_certificate_arn
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app_tg.arn
  }
}

resource "aws_ecs_cluster" "app_cluster" {
  name = "app-cluster"
}

resource "aws_iam_role" "ecs_task_execution" {
  name = "ecsTaskExecutionRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect    = "Allow",
      Principal = { Service = "ecs-tasks.amazonaws.com" },
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_exec_managed" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_ecs_task_definition" "app_task" {
  family                   = "app-task"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn
  container_definitions = jsonencode([
    {
      name         = "app"
      image        = var.container_image
      portMappings = [{ containerPort = 80, protocol = "tcp" }]
      logConfiguration = {
        logDriver = "awslogs",
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.app_logs.name,
          "awslogs-region"        = var.region,
          "awslogs-stream-prefix" = "app"
        }
      }
      environment = []
      secrets     = [{ name = "DB_PASSWORD", valueFrom = aws_secretsmanager_secret_version.db_secret.arn }]
    }
  ])
}

resource "aws_ecs_service" "app_service" {
  name            = "app-service"
  cluster         = aws_ecs_cluster.app_cluster.id
  task_definition = aws_ecs_task_definition.app_task.arn
  desired_count   = 1
  launch_type     = "FARGATE"
  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs_sg.id]
    assign_public_ip = false
  }
  load_balancer {
    target_group_arn = aws_lb_target_group.app_tg.arn
    container_name   = "app"
    container_port   = 80
  }
  depends_on = [aws_lb_listener.https_listener]
}

resource "aws_cloudwatch_log_group" "app_logs" {
  name              = "/ecs/app"
  retention_in_days = 7
  kms_key_id        = var.kms_key_id
}

resource "aws_secretsmanager_secret" "db_secret" {
  name        = "db-credentials"
  description = "PostgreSQL credentials"
  kms_key_id  = var.kms_key_id
}

resource "aws_secretsmanager_secret_version" "db_secret" {
  secret_id     = aws_secretsmanager_secret.db_secret.id
  secret_string = jsonencode({ username = var.db_username, password = var.db_password })
}

resource "aws_db_instance" "postgres" {
  identifier                          = "app-db"
  engine                              = "postgres"
  engine_version                      = "14.9"
  instance_class                      = "db.t3.micro"
  allocated_storage                   = 20
  storage_type                        = "gp2"
  username                            = var.db_username
  password                            = var.db_password
  db_subnet_group_name                = aws_db_subnet_group.db_subnet.id
  vpc_security_group_ids              = [aws_security_group.ecs_sg.id]
  multi_az                            = false
  publicly_accessible                 = false
  deletion_protection                 = true
  backup_retention_period             = 7
  enabled_cloudwatch_logs_exports     = ["postgresql"]
  performance_insights_enabled        = true
  monitoring_interval                 = 60
  iam_database_authentication_enabled = true
  skip_final_snapshot                 = true
  tags                                = { Name = "app-db" }

  storage_encrypted = true
}

resource "aws_db_subnet_group" "db_subnet" {
  name       = "db-subnet-group"
  subnet_ids = aws_subnet.private[*].id
  tags       = { Name = "db-subnet-group" }
}

resource "aws_s3_bucket" "alb_logs" {
  bucket        = "${var.project_prefix}-alb-logs"
  acl           = "private"
  force_destroy = true
  tags          = { Name = "alb-logs" }
}

resource "aws_s3_bucket_public_access_block" "alb_logs_block" {
  bucket                  = aws_s3_bucket.alb_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "alb_logs_versioning" {
  bucket = aws_s3_bucket.alb_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "rds_monitoring_role" {
  name = "rds-monitoring-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect    = "Allow",
      Principal = { Service = "monitoring.rds.amazonaws.com" },
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitoring_policy" {
  role       = aws_iam_role.rds_monitoring_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

output "alb_dns_name" {
  value = aws_lb.app_alb.dns_name
}

output "rds_endpoint" {
  value = aws_db_instance.postgres.endpoint
}

files.terraform/variables.tf:
# Terraform variables
variable "region" {
  description = "AWS region"
  type        = string
  default     = "eu-central-1"
}

variable "azs" {
  description = "Availability zones"
  type        = list(string)
  default     = ["eu-central-1a", "eu-central-1b"]
}

variable "vpc_cidr" {
  description = "VPC CIDR block"
  type        = string
  default     = "10.0.0.0/16"
}

variable "project_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "myapp"
}

variable "acm_certificate_arn" {
  description = "ARN of ACM certificate for ALB HTTPS"
  type        = string
}

variable "container_image" {
  description = "Docker image for the application"
  type        = string
  default     = "myapp:latest"
}

variable "kms_key_id" {
  description = "KMS key for encrypting logs and secrets"
  type        = string
}

variable "db_username" {
  description = "Database username"
  type        = string
  default     = "admin"
}

variable "db_password" {
  description = "Database password"
  type        = string
  sensitive   = true
}

files.terraform/security_support.tf:
resource "aws_s3_bucket" "infraarch_access_logs" {
  bucket_prefix = "infraarch-access-"
  force_destroy = false
}

resource "aws_s3_bucket_logging" "infraarch_alb_logs" {
  bucket = "${aws_s3_bucket.alb_logs.id}"
  target_bucket = "${aws_s3_bucket.infraarch_access_logs.id}"
  target_prefix = "s3/alb_logs/"
  depends_on = [aws_s3_bucket_policy.infraarch_access_logs]
}

resource "aws_s3_bucket_policy" "infraarch_access_logs" {
  bucket = "${aws_s3_bucket.infraarch_access_logs.id}"
  policy = "{\"Version\": \"2012-10-17\", \"Statement\": [{\"Sid\": \"RequireTLS\", \"Effect\": \"Deny\", \"Principal\": \"*\", \"Action\": \"s3:*\", \"Resource\": [\"${aws_s3_bucket.infraarch_access_logs.arn}\", \"${aws_s3_bucket.infraarch_access_logs.arn}/*\"], \"Condition\": {\"Bool\": {\"aws:SecureTransport\": \"false\"}}}, {\"Effect\": \"Allow\", \"Principal\": {\"Service\": \"logging.s3.amazonaws.com\"}, \"Action\": \"s3:PutObject\", \"Resource\": \"${aws_s3_bucket.infraarch_access_logs.arn}/s3/alb_logs/*\", \"Condition\": {\"StringEquals\": {\"aws:SourceAccount\": \"${data.aws_caller_identity.infraarch_security.account_id}\"}, \"ArnLike\": {\"aws:SourceArn\": \"${aws_s3_bucket.alb_logs.arn}\"}}}]}"
}

resource "aws_s3_bucket_public_access_block" "infraarch_access_logs" {
  bucket = "${aws_s3_bucket.infraarch_access_logs.id}"
  block_public_acls = true
  block_public_policy = true
  ignore_public_acls = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "infraarch_access_logs" {
  bucket = "${aws_s3_bucket.infraarch_access_logs.id}"
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "infraarch_access_logs" {
  bucket = "${aws_s3_bucket.infraarch_access_logs.id}"
  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_caller_identity" "infraarch_security" {
}

data "aws_partition" "infraarch_security" {
}

data "aws_region" "infraarch_security" {
}

resource "aws_cloudwatch_log_group" "infraarch_vpc_flow" {
  name_prefix = "/infraarch/vpc-flow-"
  retention_in_days = 365
  kms_key_id = "${aws_kms_key.infraarch_security.arn}"
}

resource "aws_flow_log" "infraarch_main" {
  vpc_id = "${aws_vpc.main.id}"
  traffic_type = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination = "${aws_cloudwatch_log_group.infraarch_vpc_flow.arn}"
  iam_role_arn = "${aws_iam_role.infraarch_vpc_flow.arn}"
  depends_on = [aws_iam_role_policy.infraarch_vpc_flow]
}

resource "aws_iam_role" "infraarch_vpc_flow" {
  name_prefix = "infraarch-flow-"
  assume_role_policy = "{\"Version\": \"2012-10-17\", \"Statement\": [{\"Effect\": \"Allow\", \"Principal\": {\"Service\": \"vpc-flow-logs.amazonaws.com\"}, \"Action\": \"sts:AssumeRole\", \"Condition\": {\"StringEquals\": {\"aws:SourceAccount\": \"${data.aws_caller_identity.infraarch_security.account_id}\"}}}]}"
}

resource "aws_iam_role_policy" "infraarch_vpc_flow" {
  name_prefix = "infraarch-flow-"
  role = "${aws_iam_role.infraarch_vpc_flow.id}"
  policy = "{\"Version\": \"2012-10-17\", \"Statement\": [{\"Effect\": \"Allow\", \"Action\": [\"logs:CreateLogStream\", \"logs:PutLogEvents\", \"logs:DescribeLogStreams\"], \"Resource\": \"${aws_cloudwatch_log_group.infraarch_vpc_flow.arn}:*\"}, {\"Effect\": \"Allow\", \"Action\": [\"logs:DescribeLogGroups\"], \"Resource\": \"*\"}]}"
}

resource "aws_kms_alias" "infraarch_security" {
  name_prefix = "alias/infraarch-security-"
  target_key_id = "${aws_kms_key.infraarch_security.key_id}"
}

resource "aws_kms_key" "infraarch_security" {
  description = "Infrastructure security encryption"
  enable_key_rotation = true
  deletion_window_in_days = 30
  policy = "{\"Version\": \"2012-10-17\", \"Statement\": [{\"Sid\": \"AccountAdministration\", \"Effect\": \"Allow\", \"Principal\": {\"AWS\": \"arn:${data.aws_partition.infraarch_security.partition}:iam::${data.aws_caller_identity.infraarch_security.account_id}:root\"}, \"Action\": \"kms:*\", \"Resource\": \"*\"}, {\"Sid\": \"ScopedLogEncryption\", \"Effect\": \"Allow\", \"Principal\": {\"Service\": \"logs.${data.aws_region.infraarch_security.name}.${data.aws_partition.infraarch_security.dns_suffix}\"}, \"Action\": [\"kms:Encrypt\", \"kms:Decrypt\", \"kms:ReEncrypt*\", \"kms:GenerateDataKey*\", \"kms:DescribeKey\"], \"Resource\": \"*\", \"Condition\": {\"ArnLike\": {\"kms:EncryptionContext:aws:logs:arn\": \"arn:${data.aws_partition.infraarch_security.partition}:logs:${data.aws_region.infraarch_security.name}:${data.aws_caller_identity.infraarch_security.account_id}:log-group:/infraarch/vpc-flow-*\"}}}]}"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "infraarch_alb_logs" {
  bucket = "${aws_s3_bucket.alb_logs.id}"
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
      kms_master_key_id = "${aws_kms_key.infraarch_security.arn}"
    }
  }
}

