      secrets = [{ name = "DB_PASSWORD", valueFrom = aws_secretsmanager_secret_version.db_secret.arn }]
    }
  ])
}

resource "aws_ecs_service" "app_service" {
  name            = "app-service"
  cluster         = aws_ecs_cluster.app_cluster.id
  task_definition = aws_ecs_task_definition.app_task.arn
  desired_count   = 1
  launch_type     = "FARGATE"
  network_configuration {
    subnets         = aws_subnet.private[*].id
    security_groups = [aws_security_group.ecs_sg.id]
    assign_public_ip = false
  }
  load_balancer {
    target_group_arn = aws_lb_target_group.app_tg.arn
    container_name   = "app"
    container_port   = 80
  }
  depends_on = [aws_lb_listener.https_listener]
}

resource "aws_cloudwatch_log_group" "app_logs" {
  name = "/ecs/app"
  retention_in_days = 7
  kms_key_id = var.kms_key_id
}

resource "aws_secretsmanager_secret" "db_secret" {
  name = "db-credentials"
  description = "PostgreSQL credentials"
  kms_key_id = var.kms_key_id
}

resource "aws_secretsmanager_secret_version" "db_secret" {
  secret_id = aws_secretsmanager_secret.db_secret.id
  secret_string = jsonencode({ username = var.db_username, password = var.db_password })
}

resource "aws_db_instance" "postgres" {
  identifier = "app-db"
  engine = "postgres"
  engine_version = "14.9"
  instance_class = "db.t3.micro"
  allocated_storage = 20
  storage_type = "gp2"
  username = var.db_username
  password = var.db_password
  db_subnet_group_name = aws_db_subnet_group.db_subnet.id
  vpc_security_group_ids = [aws_security_group.ecs_sg.id]
  multi_az = false
  publicly_accessible = false
  deletion_protection = true
  backup_retention_period = 7
  enabled_cloudwatch_logs_exports = ["postgresql"]
  performance_insights_enabled = true
  monitoring_interval = 60
  iam_database_authentication_enabled = true
  skip_final_snapshot = true
  tags = { Name = "app-db" }
}

resource "aws_db_subnet_group" "db_subnet" {
  name       = "db-subnet-group"
  subnet_ids = aws_subnet.private[*].id
  tags = { Name = "db-subnet-group" }
}

resource "aws_s3_bucket" "alb_logs" {
  bucket = "${var.project_prefix}-alb-logs"
  acl    = "private"
  force_destroy = true
  tags = { Name = "alb-logs" }
}

resource "aws_s3_bucket_public_access_block" "alb_logs_block" {
  bucket = aws_s3_bucket.alb_logs.id
  block_public_acls   = true
  block_public_policy = true
  ignore_public_acls  = true
  restrict_public_buckets = true
}

resource "aws_lb_logging" "alb_logging" {
  load_balancer_arn = aws_lb.app_alb.arn
  bucket = aws_s3_bucket.alb_logs.bucket
  enabled = true
}

resource "aws_iam_role" "rds_monitoring_role" {
  name = "rds-monitoring-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Principal = { Service = "monitoring.rds.amazonaws.com" },
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitoring_policy" {
  role       = aws_iam_role.rds_monitoring_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

output "alb_dns_name" {
  value = aws_lb.app_alb.dns_name
}

output "rds_endpoint" {
  value = aws_db_instance.postgres.endpoint
}

