}

resource "aws_db_subnet_group" "rds_subnet" {
  name       = "rds-subnet-group"
  subnet_ids = aws_subnet.private[*].id
}

resource "aws_security_group" "rds_sg" {
  name        = "rds-sg"
  description = "RDS access from ECS"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs_sg.id]
  }
  # No egress rule defined to avoid unrestricted egress
}

resource "aws_iam_role" "rds_monitoring" {
  name = "rds-monitoring-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect    = "Allow",
      Principal = { Service = "monitoring.rds.amazonaws.com" },
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_policy" "rds_monitoring_policy" {
  name = "rds-monitoring-policy"
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect   = "Allow",
      Action   = ["logs:PutLogEvents", "logs:CreateLogStream", "cloudwatch:PutMetricData"],
      Resource = "*"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitor_attach" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = aws_iam_policy.rds_monitoring_policy.arn
}

# Secrets Manager
resource "aws_secretsmanager_secret" "db_secret" {
  name = "app-db-secret"
}

resource "aws_secretsmanager_secret_version" "db_secret_version" {
  secret_id     = aws_secretsmanager_secret.db_secret.id
  secret_string = jsonencode({ username = var.db_username, password = var.db_password })
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "app_logs" {
  name              = "/ecs/app"
  retention_in_days = 14
}

# Random suffix for bucket names
resource "random_id" "suffix" {
  byte_length = 4
}

# Data sources

data "aws_availability_zones" "available" {}

# Outputs
output "alb_dns" {
  value = aws_lb.alb.dns_name
}

output "rds_endpoint" {
  value = aws_db_instance.postgres.endpoint
}

